async function bounded(req,max){need(Number(req.headers.get('content-length')||0)<=max,'Request too large',413);const reader=req.body?.getReader();if(!reader)return new Uint8Array();let n=0,parts=[];while(true){const {value,done}=await reader.read();if(done)break;n+=value.length;if(n>max){await reader.cancel();throw new HttpError('Request too large',413)}parts.push(value)}const bytes=new Uint8Array(n);let at=0;for(const p of parts){bytes.set(p,at);at+=p.length}return bytes}
