function cleanProfileLinks(input){need(Array.isArray(input)&&input.length<=5,'Add up to 5 links.');return input.map(item=>{need(item&&typeof item==='object','Invalid link');const raw=typeof item.url==='string'?item.url.trim():'';need(raw.length>0&&raw.length<=300,'Each link needs a web address (up to 300 characters).');let url;try{url=new URL(/^https?:\/\//i.test(raw)?raw:'https://'+raw)}catch{throw new HttpError('This link is not valid: '+raw.slice(0,60))}need(['http:','https:'].includes(url.protocol)&&url.hostname.includes('.')&&!url.username&&!url.password,'This link is not valid: '+raw.slice(0,60));const label=typeof item.label==='string'?item.label.replace(/\s+/g,' ').trim().slice(0,40):'';return {label:label||url.hostname.replace(/^www\./,''),url:url.href}})}
async function user(req,db){const token=cookie(req,'wm_session');if(!/^[a-f0-9]{64}$/.test(token||''))return null;return one(db,"SELECT u.id,COALESCE(NULLIF(d.display_name,''),u.name) name,u.email,CASE WHEN d.picture_id IS NOT NULL THEN '/avatar/'||u.id||'?v='||d.updated_at ELSE COALESCE(NULLIF(u.picture,''),'/assets/default-avatar.svg') END picture,CASE WHEN d.cover_id IS NOT NULL THEN '/cover/'||u.id||'?v='||d.updated_at ELSE '/assets/profile-cover.webp' END cover,COALESCE(d.bio,'') bio,(SELECT verified FROM wm_public_users vu WHERE vu.id=u.id) verified,(SELECT trusted_seller FROM wm_public_users vu WHERE vu.id=u.id) trusted_seller,COALESCE(r.role,'member') role FROM sessions s JOIN users u ON s.user_id=u.id LEFT JOIN wm_profile_details d ON d.user_id=u.id LEFT JOIN wm_roles r ON r.user_id=u.id WHERE s.token_hash=? AND s.expires_at>?",await digest(token),now())}
