async function threadAccess(db,id,u){const t=await one(db,'SELECT * FROM wm_threads WHERE id=?',id);need(t&&!t.is_deal&&(t.buyer_id===u.id||t.seller_id===u.id),'Chat not found',404);t.post_intent=t.post_id?(await one(db,'SELECT post_intent FROM wm_posts WHERE id=?',t.post_id))?.post_intent:null;const peer=t.buyer_id===u.id?t.seller_id:t.buyer_id;t.blocked=await isBlocked(db,u.id,peer);t.blocked_by_me=!!await one(db,'SELECT 1 FROM wm_user_blocks WHERE user_id=? AND target_id=?',u.id,peer);t.preferences=await one(db,"SELECT archived,muted,deleted_before FROM wm_chat_preferences WHERE user_id=? AND kind='private' AND chat_id=?",u.id,id)||{archived:0,muted:0,deleted_before:0};t.need_posts=await rows(db,"SELECT p.id,p.user_id,p.title,p.price,(SELECT 'ID No - '||number FROM wm_listing_ids WHERE post_id=p.id) listing_code FROM wm_thread_posts c JOIN wm_posts p ON p.id=c.post_id WHERE c.thread_id=? AND p.post_intent='need' AND p.status='approved' AND p.deleted_at IS NULL ORDER BY c.created_at DESC,p.id LIMIT 20",id);return t}
