async function friendExtras(db,u,people){if(!people.length)return people;try{const ids=[...new Set(people.map(p=>p.id))],mine=new Set((await rows(db,"SELECT CASE WHEN from_id=? THEN to_id ELSE from_id END id FROM wm_friend_requests WHERE status='accepted' AND (from_id=? OR to_id=?)",u.id,u.id,u.id)).map(r=>r.id)),q=ids.map(()=>'?').join(',');
 const pairs=await rows(db,"SELECT from_id,to_id FROM wm_friend_requests WHERE status='accepted' AND (from_id IN ("+q+") OR to_id IN ("+q+"))",...ids,...ids),count=new Map();for(const r of pairs)for(const [a,b] of [[r.from_id,r.to_id],[r.to_id,r.from_id]])if(ids.includes(a)&&mine.has(b))count.set(a,(count.get(a)||0)+1);
 let seen=new Map();try{seen=new Map((await rows(db,'SELECT user_id,seen_at FROM wm_presence WHERE user_id IN ('+q+')',...ids)).map(r=>[r.user_id,r.seen_at]))}catch{}for(const p of people){p.mutual=count.get(p.id)||0;p.seen_at=seen.get(p.id)||null}}catch{}return people}
