async function groupAccess(db,id,u){const g=await one(db,'SELECT g.* FROM wm_groups g JOIN wm_group_members m ON m.group_id=g.id WHERE g.id=? AND m.user_id=?',id,u.id);need(g,'Join this group to continue',403);need(!await one(db,"SELECT 1 FROM wm_chat_preferences WHERE user_id=? AND kind='group' AND chat_id=? AND blocked=1",u.id,id),'This group is blocked. Unblock it from Messenger options.',403);return g}
