export function listingPrice(value,optional=false){if(optional&&(value===null||value===undefined||value===''))return null;if(typeof value==='number')return amount(value);need(typeof value==='string'&&value.length<=40,'Enter a price like 10000 or 8.5k');const normalized=value.trim().replace(/[০-৯]/g,c=>String(c.charCodeAt(0)-2534)).replace(/[,৳\s]/g,'').toLowerCase();need(/^\d+(?:\.\d{1,3})?k?$/.test(normalized),'Enter a price like 10000 or 8.5k');const [whole,fraction='']=normalized.replace(/k$/,'').split('.');return amount(normalized.endsWith('k')?Number(whole)*1000+Number(fraction.padEnd(3,'0')):Number(normalized))}
export function hasExternalContact(value){const normalized=value.normalize('NFKC').toLowerCase().replace(/[০-৯]/g,c=>String(c.charCodeAt(0)-2534));return /(?:whats?\s*app|whatsap|ওয়া?টস?অ্যা?প|হোয়াটসঅ্যাপ|wa\.me|api\.whatsapp|chat\.whatsapp|t\.me\/|telegram\s*[:@]|imo\s*[:+@]|(?:call|contact|phone|mobile|যোগাযোগ|কল|ফোন|নাম্বার|নম্বর)\s*(?:me|us|করুন|করো|দিন)?\s*[:+]?\s*\d{5,}|(?:\+?88[\s.-]*)?01[3-9](?:[\s().-]*\d){8}|[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,})/i.test(normalized)||/(?:\+?88)?01[3-9]\d{8}/.test(normalized.replace(/[\s().-]/g,''))}
const feedSelect=postSelect.replace('SELECT p.*','SELECT p.*,f.feed_at,f.shared_by_id,f.share_id,su.name shared_by_name')+" JOIN (SELECT id post_id,COALESCE(bumped_at,created_at) feed_at,NULL shared_by_id,NULL share_id FROM wm_posts UNION ALL SELECT post_id,created_at,user_id,id FROM wm_post_shares) f ON f.post_id=p.id LEFT JOIN wm_public_users su ON su.id=f.shared_by_id";
async function postInput(db,d,u,group){if(d.postIntent==='normal'){d.postIntent='sell';d.kind='Community post';d.price=null;d.gameCategory='community';d.customGameName='';d.priceFormat='full'}const postIntent=d.postIntent??'sell';need(['sell','need'].includes(postIntent),'Invalid post type');const optionalText=(value,max,label)=>value===undefined||value===''?'':text(value,max,label);const title=text(d.title,100,'title'),details=postIntent==='need'||d.kind==='Community post'?optionalText(d.details,2000,'details'):text(d.details,2000,'description'),description=postIntent==='need'?optionalText(d.description,5000,'description'):'',price=listingPrice(d.price,true),gameCategory=d.gameCategory||(d.kind==='Game ID'?'free-fire':'community'),priceFormat=d.priceFormat||(typeof d.price==='string'&&/k\s*$/i.test(d.price)?'compact':'full');need(GAME_CATEGORIES.includes(gameCategory),'Choose a game category');const customGameName=gameCategory==='custom'?text(d.customGameName,60,'custom game name'):'';need(!customGameName||!hasExternalContact(customGameName),'Use a game name without contact details');need(['full','compact'].includes(priceFormat),'Invalid price format');need(['Game ID','Digital item','Community post'].includes(d.kind),'Invalid listing type');if(postIntent==='sell'&&d.kind==='Game ID')need(price!==null&&price>0,'Game ID price is required');let rangeId=null;if(group){await groupAccess(db,group,u);if(price!==null){const range=await one(db,'SELECT id FROM wm_group_ranges WHERE group_id=? AND min_price<=? AND (max_price IS NULL OR max_price>=?) ORDER BY CASE WHEN max_price IS NULL THEN 1 ELSE 0 END,(max_price-min_price),min_price DESC LIMIT 1',group,price,price);need(range,'No matching price range. Ask the group admin to add one.');rangeId=range.id}}need(Array.isArray(d.media)&&d.media.length<=51,'Up to 50 photos and 1 video');need(d.media.every(a=>typeof a?.id==='string'),'Invalid media');const ids=d.media.map(a=>a.id);need(new Set(ids).size===ids.length,'Remove duplicate photos');const found=ids.length?await rows(db,'SELECT id,type FROM wm_uploads WHERE user_id=? AND id IN ('+ids.map(()=>'?').join(',')+')',u.id,...ids):[];need(found.length===ids.length,'Upload not found');need(found.every(a=>a.type.startsWith('image/')||a.type.startsWith('video/')),'Posts support photos and video');const byId=new Map(found.map(a=>[a.id,a]));const attachments=ids.map(id=>({...byId.get(id),url:'/media/'+id}));const images=attachments.filter(a=>a.type.startsWith('image/')).length,videos=attachments.length-images;need(images<=50&&videos<=1,'Up to 50 photos and 1 video');if(d.mediaMode==='photos')need(images>=1,'Add at least one photo');if(d.mediaMode==='video')need(videos===1,'Add a video');// Free Fire IDs can say Male or Female (optional). Other games never have it.
 const idGender=gameCategory==='free-fire'&&['male','female'].includes(d.idGender)?d.idGender:null;
 return {title,details,description,postIntent,price,rangeId,attachments,gameCategory,priceFormat,customGameName,idGender}}
