 const ids=d.groupIds??[];need(Array.isArray(ids)&&ids.length<=20&&ids.every(id=>typeof id==='string'),'Choose up to 20 joined groups');need(new Set(ids).size===ids.length,'Remove duplicate groups');const placements=[];
