async function handoverAction(env,db,d,u,input){
 const buyer=u.id===d.buyer_id,seller=u.id===d.seller_id,time=now();
 need(d.flow===1,'Secure handover is available on protected deals',409);need(['active','awaiting_final','disputed'].includes(d.status),'This deal is closed',409);need(d.funded_at,'Secure handover opens after the Admin confirms payment',409);
 need(await dataKeys(env),'Secure handover is being set up by the Owner. For now, share login details in this Deal Room only after the Admin confirms payment.',503);
 if(input.action==='ready'){
  need(buyer,'Only the buyer can open the handover',403);
  await db.batch([stmt(db,'INSERT INTO wm_deal_handover(deal_id,buyer_ready_at) VALUES(?,?) ON CONFLICT(deal_id) DO UPDATE SET buyer_ready_at=COALESCE(wm_deal_handover.buyer_ready_at,excluded.buyer_ready_at)',d.id,time),stmt(db,"INSERT INTO wm_deal_events(deal_id,user_id,action,created_at) SELECT ?,?,'handover_ready',? WHERE NOT EXISTS(SELECT 1 FROM wm_deal_events WHERE deal_id=? AND action='handover_ready')",d.id,u.id,time,d.id)]);
  return reply({ok:true});
 }
 if(input.action==='submit'){
  need(seller,'Only the seller sends login details',403);const h=await one(db,'SELECT buyer_ready_at FROM wm_deal_handover WHERE deal_id=?',d.id);need(h?.buyer_ready_at,'Wait until the buyer taps Ready',409);
  const field=(v,max,label,optional=false)=>optional&&(v===undefined||v==='')?'':text(v,max,label);
  const data={method:field(input.method,60,'login method'),login:field(input.login,200,'login ID or email',true),password:field(input.password,200,'password',true),note:field(input.note,600,'note or code',true)};
  need(data.login||data.password||data.note,'Add the login ID, password or a login code');
  const sealed=await seal(env,data,'handover:'+d.id);
  const result=await db.batch([stmt(db,'UPDATE wm_deal_handover SET payload=?,submitted_at=?,submit_count=submit_count+1,revealed_at=NULL WHERE deal_id=?',sealed,time,d.id),stmt(db,"INSERT INTO wm_deal_events(deal_id,user_id,action,created_at) SELECT ?,?,'handover_submitted',? WHERE changes()=1",d.id,u.id,time)]);
  need(result[0].meta.changes===1,'Handover changed. Refresh and retry.',409);return reply({ok:true});
 }
 if(input.action==='reveal'){
  need(buyer,'Only the buyer can open the login details',403);
  const h=await one(db,'SELECT payload FROM wm_deal_handover WHERE deal_id=? AND payload IS NOT NULL',d.id);need(h,'No unopened login details. Ask the seller to send them again.',409);
  const data=await unseal(env,h.payload,'handover:'+d.id);
  // One-time reveal: the encrypted copy is removed in the same step that returns it.
  const result=await db.batch([stmt(db,'UPDATE wm_deal_handover SET payload=NULL,revealed_at=? WHERE deal_id=? AND payload=?',time,d.id,h.payload),stmt(db,"INSERT INTO wm_deal_events(deal_id,user_id,action,created_at) SELECT ?,?,'handover_revealed',? WHERE changes()=1",d.id,u.id,time)]);
  need(result[0].meta.changes===1,'These details were already opened',409);
  return reply({details:data});
 }
 throw new HttpError('Invalid handover action');
}

const USERNAME_WAIT=7*86400000;
async function usernameWrite(db,id,value,actor=null){
 need(typeof value==='string','Enter a username');const name=value.trim().toLowerCase();
 need(/^[a-z][a-z0-9_]{2,23}$/.test(name)&&!['admin','owner','support','api','control','wize','market','login','settings'].includes(name),'Use 3–24 characters: start with a letter, then letters, numbers or underscores');
 const old=await one(db,'SELECT username,updated_at FROM wm_profiles WHERE user_id=?',id);
 if(old?.username===name)return {name,statement:null};
 if(actor&&actor.role!=='owner'&&(await marketRules(db)).nameRules){const problem=nameProblem(name,'username');need(!problem,problem)}
 need(!old||old.updated_at+USERNAME_WAIT<=now(),'Username can be changed again on '+new Date((old?.updated_at||now())+USERNAME_WAIT).toISOString(),409);
 need(!await one(db,'SELECT user_id FROM wm_profiles WHERE username=? AND user_id!=?',name,id),'This username is already taken',409);
 return {name,statement:stmt(db,'INSERT INTO wm_profiles(user_id,username,updated_at) VALUES(?,?,?) ON CONFLICT(user_id) DO UPDATE SET username=excluded.username,updated_at=excluded.updated_at WHERE wm_profiles.username!=excluded.username',id,name,now())};
}
function profileWriteError(error){if(/UNIQUE/i.test(error.message))throw new HttpError('This username is already taken',409);if(/username_cooldown/i.test(error.message))throw new HttpError('Username changes require 7 days between updates',409);throw error}

