 let image=null;try{image=JSON.parse(post.media||'[]').find(m=>String(m?.type||'').startsWith('image/')&&/^[a-f0-9-]{36}$/.test(m.id))}catch{}
 const title=(post.post_intent==='need'?'Need: ':'')+post.title+(post.price?' · ৳'+Number(post.price).toLocaleString('en-US'):''),description=String(post.details||'').replace(/\s+/g,' ').trim().slice(0,180)||'Game account listing';
 const tags=[['og:type','website'],['og:title',title],['og:description',description],['og:url',origin+'/post/'+post.id],...(image?[['og:image',origin+'/media/'+image.id]]:[['og:image',origin+'/icons/og-card.jpg?v=2'],['og:image:width','1200'],['og:image:height','630']])].map(([k,v])=>'<meta property="'+k+'" content="'+esc(v)+'">').join('')+'<meta name="twitter:card" content="summary_large_image">';
 return page.replace('<head>',()=>'<head>'+tags).replace(/<title>([^<]*)<\/title>/,(m,site)=>'<title>'+esc(post.title)+' · '+site+'</title>');
